select id, customer_id, coupon_codes, ship_to, attributes, transform(filter(items, x -> x.promo is not null), x -> struct(x.product_id as pid, round(x.price * 0.9, 2) as discounted_price)) as promo_lines, ship_to.city as ship_city, array_join(array_sort(coupon_codes), ',') as coupons_text, array_contains(coupon_codes, 'BUNDLE') as used_bundle from carts where size(coupon_codes) > 1;
